//#region src/config/emailjs.ts
/**
* EmailJS Configuration
* 
* To set up EmailJS for your portfolio:
* 1. Go to https://www.emailjs.com/ and sign up (it's free)
* 2. Create an email service (connect your email provider)
* 3. Create an email template with variables:
*    - {{from_name}} - sender name
*    - {{from_email}} - sender email
*    - {{subject}} - message subject
*    - {{message}} - message body
* 4. Copy your credentials from EmailJS dashboard:
*    - Service ID (looks like "service_xxxxx")
*    - Template ID (looks like "template_xxxxx")
*    - Public Key (looks like "xxxxx")
* 5. Paste them in the fields below
* 
* WARNING: Keep these credentials safe. The public key is meant to be public,
* but never commit sensitive credentials to git.
*/
var EMAILJS_CONFIG = {
	SERVICE_ID: "service_YOUR_SERVICE_ID_HERE",
	TEMPLATE_ID: "template_YOUR_TEMPLATE_ID_HERE",
	PUBLIC_KEY: "YOUR_PUBLIC_KEY_HERE"
};
var isEmailJSConfigured = () => {
	return EMAILJS_CONFIG.SERVICE_ID !== "service_YOUR_SERVICE_ID_HERE" && EMAILJS_CONFIG.TEMPLATE_ID !== "template_YOUR_TEMPLATE_ID_HERE" && EMAILJS_CONFIG.PUBLIC_KEY !== "YOUR_PUBLIC_KEY_HERE";
};
//#endregion
//#region src/hooks/useEmailJS.ts
/**
* Hook to handle EmailJS email sending
* Manages loading states and error handling
*/
function useEmailJS() {
	const [status, setStatus] = useState("idle");
	const isConfigured = isEmailJSConfigured();
	if (isConfigured && !emailjs.init) emailjs.init(EMAILJS_CONFIG.PUBLIC_KEY);
	const sendEmail = async (data) => {
		if (!isConfigured) {
			toast.error("Email service not configured. Please add your EmailJS credentials.");
			console.warn("EmailJS credentials not configured. Check src/config/emailjs.ts");
			return;
		}
		try {
			setStatus("sending");
			if ((await emailjs.send(EMAILJS_CONFIG.SERVICE_ID, EMAILJS_CONFIG.TEMPLATE_ID, {
				from_name: data.name,
				from_email: data.email,
				subject: data.subject,
				message: data.message,
				reply_to: data.email
			}, EMAILJS_CONFIG.PUBLIC_KEY)).status === 200) {
				setStatus("sent");
				toast.success("Message sent successfully! I'll get back to you soon.");
			} else throw new Error("Failed to send email");
		} catch (error) {
			setStatus("error");
			const errorMessage = error instanceof Error ? error.message : "Failed to send message. Please try again.";
			toast.error(errorMessage);
			console.error("EmailJS error:", error);
		}
	};
	const reset = () => setStatus("idle");
	return {
		status,
		sendEmail,
		reset,
		isConfigured
	};
}
